import {standardMultipliers} from '../../src/board.js';
import {DEFAULT_VALUES} from '../../src/scoring.js';
export const gameUrl='https://malstadur.mideind.is/netskrafl#!/game/7e2052d2-c7c2-11f1-9fe9-5d03dab88dd2';
export function fixture(){const m=standardMultipliers();let html='<div id="board-parent"><table><tbody>';for(let r=0;r<15;r++){html+='<tr>';for(let c=0;c<15;c++){const x=m[r][c],cls=x.word===3?'tw':x.word===2?'dw':x.letter===3?'tl':x.letter===2?'dl':'';html+=`<td id="sq_${'ABCDEFGHIJKLMNO'[r]}${c+1}" class="${cls}"></td>`;}html+='</tr>';}return html+'</tbody></table></div><div class="rack"><table><tr>'+Array.from({length:7},(_,i)=>`<td id="sq_R${i+1}"></td>`).join('')+'</tr></table></div>';}
export function screenshotFixture(){let html=fixture();const tiles={D9:'A',E9:'J',F6:'S',F7:'Í',F8:'M',F9:'A',G1:'B',G9:'X',H1:'Ý',H4:'M',H5:'Y',H6:'R',H7:'K',H8:'V',H9:'A',I1:'F',I2:'Æ',I3:'T',I4:'I',I8:'I',J1:'A',J6:'Ö',J8:'S',K4:'F',K5:'A',K6:'R',K7:'Ð',K8:'I',K9:'R',L6:'L',L8:'N',M6:'A'};for(const [coord,l]of Object.entries(tiles)){const re=new RegExp(`(<td id="sq_${coord}"[^>]*>)</td>`);html=html.replace(re,`$1<div class="tile${coord==='G9'?' blanktile':''}">${l}<span class="letterscore">${coord==='G9'?0:DEFAULT_VALUES[l]}</span></div></td>`);}for(const [i,l]of [...'EAAEFRL'].entries())html=html.replace(`<td id="sq_R${i+1}"></td>`,`<td id="sq_R${i+1}"><div class="tile racktile">${l}<span class="letterscore">${DEFAULT_VALUES[l]}</span></div></td>`);return html;}
// Position reported on 15 October: ten committed tiles, with a gray E draft at C2.
export function draftScreenshotFixture({draft=true}={}){
 let html=fixture();const tiles={F5:'Þ',F6:'Ö',F7:'G',F8:'U',G8:'N',H8:'U',I6:'F',I7:'E',I8:'N',I9:'I'};
 if(draft)tiles.C2='E';for(const [coord,l]of Object.entries(tiles))html=html.replace(new RegExp(`(<td id="sq_${coord}"[^>]*>)</td>`),`$1<div class="tile${coord==='C2'?' gray':''}">${l}<span class="letterscore">${DEFAULT_VALUES[l]}</span></div></td>`);
 for(const [i,l]of [...(draft?' KRFÆUS':'EKRFÆUS')].entries())if(l!==' ')html=html.replace(`<td id="sq_R${i+1}"></td>`,`<td id="sq_R${i+1}"><div class="tile gray">${l}<span class="letterscore">${DEFAULT_VALUES[l]}</span></div></td>`);
 return '<style>.tile{background:rgb(140,80,50)}.gray{background:rgb(70,75,70)}</style>'+html+'<div class="movelist"><div class="move"><span class="wordmove"><i>UNUN</i> (8F)</span></div><div class="move"><span class="wordmove">(F5) <i>ÞÖGU</i></span></div><div class="move"><span class="wordmove"><i>FENI</i> (I6)</span></div></div>';
}
